import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"历史记录","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/history.md","filePath":"zh-CN/user-guide/settings/history.md","lastUpdated":1786537234000}'),s={name:"zh-CN/user-guide/settings/history.md"};function n(i,t,l,d,c,h){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="历史记录" tabindex="-1">历史记录 <a class="header-anchor" href="#历史记录" aria-label="Permalink to &quot;历史记录&quot;">​</a></h1><p>两个 Tab，各自独立:<strong>搜索记录</strong>和<strong>关键字记录</strong>。</p><h2 id="搜索记录" tabindex="-1">搜索记录 <a class="header-anchor" href="#搜索记录" aria-label="Permalink to &quot;搜索记录&quot;">​</a></h2><p>记录你实际打开过的结果，以便下次搜索类似内容时能优先展示。</p><p>搜索记录会同时记住打开的路径和当时使用的查询。以后输入与该查询模糊匹配的文字时，快速窗口、内联窗口和完整窗口都能重新召回仍然存在的路径并优先显示；例如用 <code>bcomp</code> 打开 <code>BCompare.exe</code> 后，搜索 <code>bc</code> 也能让它回到前列。内联搜索会把当前文件夹范围内的匹配放进<strong>当前文件夹</strong>，其余放进<strong>全局搜索</strong>；不存在的路径会被忽略，同一路径只会显示一次。</p><ul><li><strong>启用历史记录</strong> 复选框 —— 打开/关闭记录功能;关闭后已有的记录会保留，只是不再新增。</li><li><strong>搜索框</strong> —— 按关键词过滤当前显示的历史列表。</li><li>每条记录都可以单独删除，也可以用<strong>清空全部记录</strong>一次性清空。</li></ul><h2 id="关键字记录" tabindex="-1">关键字记录 <a class="header-anchor" href="#关键字记录" aria-label="Permalink to &quot;关键字记录&quot;">​</a></h2><p>记录你在快速窗口搜索框里实际输入过的原始文字(而不是打开了什么)，方便用<a href="./../hotkeys.html#全局热键">关键字历史热键</a>(默认 <code>Alt+Up</code> / <code>Alt+Down</code>)翻阅最近的查询。</p><ul><li>同样有<strong>启用历史记录</strong>开关、搜索过滤、单条删除和<strong>清空全部记录</strong>按钮，只是作用对象是关键字而不是打开过的结果。</li></ul>',9)])])}const u=e(s,[["render",n]]);export{p as __pageData,u as default};
